export const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

const mem = {};
const lastKnownUpdatedAt = {}; // tracks, per key, the newest updated_at this session has actually seen — either from loading or from its own last successful save
const writeQueues = {}; // per-key chain of promises — guarantees saves to the same key are applied in the order they were *called*, not the order their network requests happen to finish. Without this, e.g. deleting something and then quickly restoring could let the delete's save straggle and land AFTER the restore's, silently reverting it with no error or warning.
function queueWrite(k, fn) {
  const prior = writeQueues[k] || Promise.resolve();
  const next = prior.then(fn, fn); // run fn regardless of whether the prior write succeeded or failed
  writeQueues[k] = next.catch(() => {}); // keep the chain alive even after an error, without leaking unhandled rejections
  return next;
}
const store = {
  async get(k) {
    try {
      const { data, error } = await supabase.from("kv_store").select("value, updated_at").eq("key", k).maybeSingle();
      if (error) throw error;
      if (data) lastKnownUpdatedAt[k] = data.updated_at;
      return data ? { value: data.value } : null;
    } catch (e) { return k in mem ? { value: mem[k] } : null; }
  },
  async set(k, v, force) {
    // Before writing, check whether the database has been updated more
    // recently than what this session last saw. If so, some other open
    // tab/device saved something after this session last loaded or saved —
    // blindly overwriting it here would silently destroy that change,
    // which is exactly what happened with the missing client. Instead,
    // stop and let save() below decide what to do about it.
    if (!force) {
      try {
        const { data: current } = await supabase.from("kv_store").select("updated_at").eq("key", k).maybeSingle();
        if (current?.updated_at && lastKnownUpdatedAt[k] && current.updated_at > lastKnownUpdatedAt[k]) {
          const conflictErr = new Error("Another session saved newer data first.");
          conflictErr.isStaleConflict = true;
          throw conflictErr;
        }
      } catch (e) {
        if (e.isStaleConflict) throw e;
        // If the conflict-check itself couldn't run (e.g. offline), fall
        // through and attempt the save anyway rather than blocking forever.
      }
    }
    // Deliberately does NOT fall back to memory-only storage on failure —
    // that used to silently report success while quietly not persisting
    // anything, which meant a real save failure looked identical to a
    // successful one until the tab was closed and the data was just gone.
    // Letting the error through means the caller (save(), below) can
    // actually warn about it instead of hiding it.
    const nowIso = new Date().toISOString();
    const { error } = await supabase.from("kv_store").upsert({ key: k, value: v, updated_at: nowIso });
    if (error) throw error;
    lastKnownUpdatedAt[k] = nowIso;
    mem[k] = v; // keep as a same-session cache only, not a substitute for a real save
    return { value: v };
  },
};
async function load(k, fb) {
  try { const r = await store.get(k); return r && r.value !== undefined && r.value !== null ? r.value : fb; }
  catch (e) { return fb; }
}
async function save(k, v) {
  try {
    await queueWrite(k, () => store.set(k, v));
  } catch (e) {
    if (e.isStaleConflict) {
      const overwrite = confirm(
        "⚠️ Another open tab or device saved newer changes to " + k.replace("velebit:", "") + " since this page last loaded data.\n\n" +
        "Click OK to save your version anyway — this will overwrite their changes.\n" +
        "Click Cancel to reload this page instead and get the latest data (your change here will be lost, so copy anything important first if you cancel)."
      );
      if (overwrite) {
        try {
          await queueWrite(k, () => store.set(k, v, true));
        } catch (e2) {
          console.error("Forced save failed for", k, e2);
          alert("Still couldn't save. Please try again.\n\nTechnical detail: " + (e2?.message || e2));
        }
      } else {
        window.location.reload();
      }
      return;
    }
    console.error("Save failed for", k, e);
    // A failed save must never be silent — the screen would otherwise keep
    // showing data that was never actually written to the database.
    alert(
      "⚠️ Couldn't save your changes to the database (" + k.replace("velebit:", "") + ").\n\n" +
      "This usually means a connection problem. Please check your internet connection " +
      "and try the action again — don't assume it saved.\n\n" +
      "Technical detail: " + (e?.message || e)
    );
  }
}

/* ------------------------------------------------------------- csv export */
function csvCell(v) {
  const s = v == null ? "" : String(v);
  return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}
function csvFrom(headers, rows) {
  const head = headers.map(csvCell).join(",");
  const body = rows.map((r) => headers.map((h) => csvCell(r[h])).join(",")).join("\r\n");
  return "\ufeff" + head + "\r\n" + body; // BOM keeps Excel + Arabic happy
}
function dl(name, text, mime) {
  const blob = new Blob([text], { type: mime || "text/csv;charset=utf-8" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob); a.download = name; a.click(); URL.revokeObjectURL(a.href);
}
function customersCSV(clients) {
  const headers = ["Display Name", "Company Name", "Email", "Phone", "Phone 2", "Billing Country", "Notes"];
  return csvFrom(headers, clients.map((c) => ({
    "Display Name": c.name, "Company Name": c.company || "", "Email": c.email || "",
    "Phone": c.phone || "", "Phone 2": c.phone2 || "", "Billing Country": c.country || "", "Notes": c.notes || "",
  })));
}
function invoicesCSV(invoices, settings) {
  const headers = ["Invoice Number", "Invoice Date", "Customer Name", "Customer Email",
    "Item Description", "Quantity", "Item Price", "Item Total", "Tax %", "Currency", "Invoice Status"];
  const rows = [];
  invoices.forEach((inv) => {
    const t = invTotals(inv, settings);
    const rate = t.vatEnabled ? Math.round(t.vatRate * 100) : 0;
    (inv.items || []).forEach((it) => {
      const q = num(it.qty), p = num(it.price);
      rows.push({
        "Invoice Number": inv.invoiceNo, "Invoice Date": inv.date,
        "Customer Name": inv.billTo?.name || "", "Customer Email": inv.billTo?.email || "",
        "Item Description": it.desc || "", "Quantity": q, "Item Price": p, "Item Total": q * p,
        "Tax %": rate, "Currency": settings.bank.currency, "Invoice Status": inv.status,
      });
    });
  });
  return csvFrom(headers, rows);
}
function expensesCSV(txns) {
  const headers = ["Date", "Expense Account", "Description", "Amount", "Tax Amount", "Notes"];
  return csvFrom(headers, txns.filter((t) => t.type === "expense").map((t) => ({
    "Date": t.date, "Expense Account": t.category, "Description": t.description || "",
    "Amount": num(t.amount), "Tax Amount": num(t.vat), "Notes": t.notes || "",
  })));
}

